package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Repeatable stress fixture; restores encrypted records and preferences after measuring. */
final class PerformanceChecks {static boolean suppressBlur;
 static int run(Instrumentation t,Context c)throws Exception{
  Map<String,Object> secure=VisualChecks.preferences(c.getSharedPreferences("secure",0)),settings=VisualChecks.preferences(NativeStore.settings(c)),updates=VisualChecks.preferences(AppUpdates.prefs(c));MainActivity[] host={null};HandlerThread framesThread=new HandlerThread("perf-frames");framesThread.start();List<Long> frames=Collections.synchronizedList(new ArrayList<>());List<long[]> stages=Collections.synchronizedList(new ArrayList<>());JSONArray timings=new JSONArray();
  try{
   JSONObject fixture=Ledger.initial();JSONArray tx=fixture.getJSONArray("transactions"),history=fixture.getJSONArray("changeLog");for(int i=0;i<1800;i++){JSONObject movement=NativeSync.transaction(i%8==0?"income":"expense",1000+i,"bank-mach","",i%8==0?"income-0":"expense-0","Comercio "+(i%50),"manual","");movement.put("id","perf-"+i).put("date",java.time.LocalDate.parse(Ledger.today()).minusDays(i%85).toString());tx.put(movement);history.put(new JSONObject().put("id","history-"+i).put("at",System.currentTimeMillis()-i*60000L).put("section","transactions").put("recordId",movement.getString("id")).put("action","edited").put("before",new JSONObject(movement.toString())).put("after",new JSONObject(movement.toString())));}
   NativeStore.settings(c).edit().putBoolean("detectionTutorialSeen",true).putBoolean("privateScreen",false).putBoolean("capture",false).putString("paymentCards","[]").commit();LocalData.restore(c,fixture);String before=LocalData.read(c).getJSONArray("transactions").toString();for(int i=0;i<4;i++){long start=SystemClock.elapsedRealtimeNanos();LocalData.read(c);timings.put(new JSONObject().put("section","read").put("ms",(SystemClock.elapsedRealtimeNanos()-start)/1000000d));}
   host[0]=(MainActivity)t.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));t.waitForIdleSync();Thread.sleep(400);MainActivity a=host[0];if(suppressBlur)t.runOnMainSync(()->a.navigationDock.frost.setVisibility(View.INVISIBLE));Window.OnFrameMetricsAvailableListener listener=(window,metric,dropped)->{frames.add(metric.getMetric(FrameMetrics.TOTAL_DURATION));stages.add(new long[]{metric.getMetric(FrameMetrics.UNKNOWN_DELAY_DURATION),metric.getMetric(FrameMetrics.ANIMATION_DURATION),metric.getMetric(FrameMetrics.LAYOUT_MEASURE_DURATION),metric.getMetric(FrameMetrics.DRAW_DURATION),metric.getMetric(FrameMetrics.COMMAND_ISSUE_DURATION),metric.getMetric(FrameMetrics.GPU_DURATION),metric.getMetric(FrameMetrics.SWAP_BUFFERS_DURATION)});};a.getWindow().addOnFrameMetricsAvailableListener(listener,new Handler(framesThread.getLooper()));String[] routes={"Movimientos","Cuentas","Explorar","Inicio","Automático","Historial","Personas","Ajustes","Movimientos","Cuentas","Explorar","Inicio"};for(String route:routes){long[] duration={0};t.runOnMainSync(()->{long start=SystemClock.elapsedRealtimeNanos();a.navigate(route);duration[0]=SystemClock.elapsedRealtimeNanos()-start;});timings.put(new JSONObject().put("section",route).put("ms",duration[0]/1000000d));Thread.sleep(320);t.waitForIdleSync();}a.getWindow().removeOnFrameMetricsAvailableListener(listener);
   List<Long> sorted=new ArrayList<>(frames);Collections.sort(sorted);int frozen=0;for(long frame:sorted)if(frame>700000000L)frozen++;JSONObject report=new JSONObject().put("version",AppUpdates.installed(c)).put("blurSuppressedForDiagnostic",suppressBlur).put("fixtureTransactions",1800).put("fixtureHistory",1800).put("timings",timings).put("frames",sorted.size()).put("frozenFrames",frozen).put("p50ms",sorted.isEmpty()?0:sorted.get(sorted.size()/2)/1000000d).put("p90ms",sorted.isEmpty()?0:sorted.get((int)(sorted.size()*.9))/1000000d).put("environment","Android 16 emulator; not Samsung performance");JSONArray stageReport=new JSONArray();String[] names={"unknownDelay","animation","layout","draw","commands","gpu","swap"};for(int i=0;i<names.length;i++){List<Long> sample=new ArrayList<>();for(long[] stage:new ArrayList<>(stages))sample.add(stage[i]);Collections.sort(sample);stageReport.put(new JSONObject().put("stage",names[i]).put("p50ms",sample.isEmpty()?0:sample.get(sample.size()/2)/1000000d));}report.put("frameStages",stageReport);Bundle result=new Bundle();result.putString("performance",report.toString());t.sendStatus(0,result);if(!before.equals(LocalData.read(c).getJSONArray("transactions").toString()))throw new Exception("Navigation changed financial records");UiSmoke.shot(t,c,"performance-home");return 1;
  }finally{if(host[0]!=null)t.runOnMainSync(()->host[0].finish());t.waitForIdleSync();NativeSync.EXEC.submit(()->{}).get(20,TimeUnit.SECONDS);VisualChecks.restore(c.getSharedPreferences("secure",0),secure);VisualChecks.restore(NativeStore.settings(c),settings);VisualChecks.restore(AppUpdates.prefs(c),updates);framesThread.quitSafely();}
 }
}
